package cn.zhuatech.insight.controller; import cn.zhuatech.insight.ai.AiProvider; import cn.zhuatech.insight.common.ApiResponse; import cn.zhuatech.insight.dto.InsightDto.*; import cn.zhuatech.insight.service.InsightService; import cn.zhuatech.insight.service.InsightPriorityService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('DOMAIN_USER','ADMIN')") public class WorkspaceController {private final InsightService service;private final AiProvider ai;private final InsightPriorityService priority;public WorkspaceController(InsightService service,AiProvider ai,InsightPriorityService priority){this.service=service;this.ai=ai;this.priority=priority;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}@PostMapping("/ai-preview") public ApiResponse<AiProvider.AiResult> preview(@RequestBody Map<String,String> body){return ApiResponse.ok(ai.execute(body.getOrDefault("prompt",""),Map.of("mode","demo")));}@PostMapping("/insight-priority") public ApiResponse<InsightPriorityService.PriorityResult> prioritize(@Valid @RequestBody InsightPriorityService.PriorityRequest request){return ApiResponse.ok("洞察优先级计算完成",priority.prioritize(request));}}
